import json,os
m=json.load(open(os.environ['STAMPED_DELIVERY_MANIFEST']))
want=['content/workspace/REPORT.md','content/workspace/analysis.py','content/workspace/results/group_results.json','content/workspace/input/upstream-methods.md','content/workspace/input/participants.tsv','content/workspace/input/sources.json','content/workspace/results/README.md','content/workspace/.gitignore','content/workspace/.codex/hooks.json','content/workspace/.cache/nilearn/README.md']
for p in want:
